`timescale 1ns/1ps
// Self-checking testbench for the design generated from pdf_example.txt
// (asap schedule). Generated by the EC551 HLS tool; do not edit.
// Prints one FAIL line per mismatch, then a PASS or FAIL summary.
module testbench;
    reg clk = 1'b0;
    reg rst = 1'b1, en = 1'b0, start = 1'b1, restart = 1'b0;
    reg in_we = 1'b0;
    reg [5:0] in_sel = 6'd0;
    reg [15:0] in_data = 16'd0;
    reg [1:0] view = 2'd0;
    reg [5:0] dbg_sel = 6'd0;
    wire [15:0] dbg_value;
    wire [11:0] fu_active;
    wire [7:0] state;
    wire done;
    integer errors = 0, checks = 0;

    hls_core dut (
        .clk(clk), .rst(rst), .en(en), .start(start), .restart(restart),
        .in_we(in_we), .in_sel(in_sel), .in_data(in_data),
        .view(view), .dbg_sel(dbg_sel), .dbg_value(dbg_value),
        .fu_active(fu_active), .state(state), .done(done)
    );

    always #5 clk = ~clk;

    // Signals change on the falling edge, so they're stable at the rising edge.
    task load(input [5:0] index, input [15:0] value);
        begin
            @(negedge clk); in_sel = index; in_data = value; in_we = 1'b1;
            @(negedge clk); in_we = 1'b0;
        end
    endtask

    // Exactly one enabled rising edge, like one press of the step button.
    task step;
        begin
            @(negedge clk); en = 1'b1;
            @(negedge clk); en = 1'b0;
        end
    endtask

    task check(input [1:0] v, input [5:0] index, input [15:0] want,
               input [8*64-1:0] what);
        begin
            view = v; dbg_sel = index; #1;
            checks = checks + 1;
            if (dbg_value !== want) begin
                errors = errors + 1;
                $display("FAIL %0s: got %0d, want %0d", what, dbg_value, want);
            end
        end
    endtask

    task check_state(input [7:0] want_state, input [11:0] want_active);
        begin
            checks = checks + 1;
            if (state !== want_state || fu_active !== want_active
                    || done !== (want_state == 8'd4)) begin
                errors = errors + 1;
                $display("FAIL state: got %0d (busy %b, done %b), want %0d (busy %b)",
                         state, fu_active, done, want_state, want_active);
            end
        end
    endtask

    initial begin
        repeat (2) @(negedge clk);
        rst = 1'b0;

        // vector 1: A=3 B=2  ->  X=5 Y=8 Z=3 Q=6
        $display("vector 1: A=3 B=2 -> expect X=5 Y=8 Z=3 Q=6");
        @(negedge clk); restart = 1'b1;
        @(negedge clk); restart = 1'b0;
        load(6'd0, 16'd3);
        load(6'd1, 16'd2);
        check(2'd3, 6'd0, 16'd3, "input A");
        check(2'd3, 6'd1, 16'd2, "input B");
        check_state(8'd0, 12'd0);
        step;
        check_state(8'd1, 12'b000000000001);
        check(2'd0, 6'd0, 16'd5, "step 1 add0 = X_1");
        step;
        check(2'd2, 6'd0, 16'd5, "after step 1 r0 = X_1");
        check_state(8'd2, 12'b000000000011);
        check(2'd0, 6'd0, 16'd8, "step 2 add0 = Y_1");
        check(2'd0, 6'd1, 16'd3, "step 2 sub0 = Z_1");
        step;
        check(2'd2, 6'd1, 16'd8, "after step 2 r1 = Y_1");
        check(2'd2, 6'd2, 16'd3, "after step 2 r2 = Z_1");
        check_state(8'd3, 12'b000000000100);
        check(2'd0, 6'd2, 16'd6, "step 3 mul0 = Q_1");
        step;
        check(2'd2, 6'd3, 16'd6, "after step 3 r3 = Q_1");
        check_state(8'd4, 12'd0);
        check(2'd1, 6'd0, 16'd5, "output X");
        check(2'd1, 6'd1, 16'd8, "output Y");
        check(2'd1, 6'd2, 16'd3, "output Z");
        check(2'd1, 6'd3, 16'd6, "output Q");

        // vector 2: A=121 B=7  ->  X=128 Y=249 Z=121 Q=847
        $display("vector 2: A=121 B=7 -> expect X=128 Y=249 Z=121 Q=847");
        @(negedge clk); restart = 1'b1;
        @(negedge clk); restart = 1'b0;
        load(6'd0, 16'd121);
        load(6'd1, 16'd7);
        check(2'd3, 6'd0, 16'd121, "input A");
        check(2'd3, 6'd1, 16'd7, "input B");
        check_state(8'd0, 12'd0);
        step;
        check_state(8'd1, 12'b000000000001);
        check(2'd0, 6'd0, 16'd128, "step 1 add0 = X_1");
        step;
        check(2'd2, 6'd0, 16'd128, "after step 1 r0 = X_1");
        check_state(8'd2, 12'b000000000011);
        check(2'd0, 6'd0, 16'd249, "step 2 add0 = Y_1");
        check(2'd0, 6'd1, 16'd121, "step 2 sub0 = Z_1");
        step;
        check(2'd2, 6'd1, 16'd249, "after step 2 r1 = Y_1");
        check(2'd2, 6'd2, 16'd121, "after step 2 r2 = Z_1");
        check_state(8'd3, 12'b000000000100);
        check(2'd0, 6'd2, 16'd847, "step 3 mul0 = Q_1");
        step;
        check(2'd2, 6'd3, 16'd847, "after step 3 r3 = Q_1");
        check_state(8'd4, 12'd0);
        check(2'd1, 6'd0, 16'd128, "output X");
        check(2'd1, 6'd1, 16'd249, "output Y");
        check(2'd1, 6'd2, 16'd121, "output Z");
        check(2'd1, 6'd3, 16'd847, "output Q");

        // vector 3: A=106 B=124  ->  X=230 Y=336 Z=106 Q=13144
        $display("vector 3: A=106 B=124 -> expect X=230 Y=336 Z=106 Q=13144");
        @(negedge clk); restart = 1'b1;
        @(negedge clk); restart = 1'b0;
        load(6'd0, 16'd106);
        load(6'd1, 16'd124);
        check(2'd3, 6'd0, 16'd106, "input A");
        check(2'd3, 6'd1, 16'd124, "input B");
        check_state(8'd0, 12'd0);
        step;
        check_state(8'd1, 12'b000000000001);
        check(2'd0, 6'd0, 16'd230, "step 1 add0 = X_1");
        step;
        check(2'd2, 6'd0, 16'd230, "after step 1 r0 = X_1");
        check_state(8'd2, 12'b000000000011);
        check(2'd0, 6'd0, 16'd336, "step 2 add0 = Y_1");
        check(2'd0, 6'd1, 16'd106, "step 2 sub0 = Z_1");
        step;
        check(2'd2, 6'd1, 16'd336, "after step 2 r1 = Y_1");
        check(2'd2, 6'd2, 16'd106, "after step 2 r2 = Z_1");
        check_state(8'd3, 12'b000000000100);
        check(2'd0, 6'd2, 16'd13144, "step 3 mul0 = Q_1");
        step;
        check(2'd2, 6'd3, 16'd13144, "after step 3 r3 = Q_1");
        check_state(8'd4, 12'd0);
        check(2'd1, 6'd0, 16'd230, "output X");
        check(2'd1, 6'd1, 16'd336, "output Y");
        check(2'd1, 6'd2, 16'd106, "output Z");
        check(2'd1, 6'd3, 16'd13144, "output Q");

        // vector 4: A=189 B=208  ->  X=397 Y=586 Z=189 Q=39312
        $display("vector 4: A=189 B=208 -> expect X=397 Y=586 Z=189 Q=39312");
        @(negedge clk); restart = 1'b1;
        @(negedge clk); restart = 1'b0;
        load(6'd0, 16'd189);
        load(6'd1, 16'd208);
        check(2'd3, 6'd0, 16'd189, "input A");
        check(2'd3, 6'd1, 16'd208, "input B");
        check_state(8'd0, 12'd0);
        step;
        check_state(8'd1, 12'b000000000001);
        check(2'd0, 6'd0, 16'd397, "step 1 add0 = X_1");
        step;
        check(2'd2, 6'd0, 16'd397, "after step 1 r0 = X_1");
        check_state(8'd2, 12'b000000000011);
        check(2'd0, 6'd0, 16'd586, "step 2 add0 = Y_1");
        check(2'd0, 6'd1, 16'd189, "step 2 sub0 = Z_1");
        step;
        check(2'd2, 6'd1, 16'd586, "after step 2 r1 = Y_1");
        check(2'd2, 6'd2, 16'd189, "after step 2 r2 = Z_1");
        check_state(8'd3, 12'b000000000100);
        check(2'd0, 6'd2, 16'd39312, "step 3 mul0 = Q_1");
        step;
        check(2'd2, 6'd3, 16'd39312, "after step 3 r3 = Q_1");
        check_state(8'd4, 12'd0);
        check(2'd1, 6'd0, 16'd397, "output X");
        check(2'd1, 6'd1, 16'd586, "output Y");
        check(2'd1, 6'd2, 16'd189, "output Z");
        check(2'd1, 6'd3, 16'd39312, "output Q");

        // vector 5: A=204 B=8  ->  X=212 Y=416 Z=204 Q=1632
        $display("vector 5: A=204 B=8 -> expect X=212 Y=416 Z=204 Q=1632");
        @(negedge clk); restart = 1'b1;
        @(negedge clk); restart = 1'b0;
        load(6'd0, 16'd204);
        load(6'd1, 16'd8);
        check(2'd3, 6'd0, 16'd204, "input A");
        check(2'd3, 6'd1, 16'd8, "input B");
        check_state(8'd0, 12'd0);
        step;
        check_state(8'd1, 12'b000000000001);
        check(2'd0, 6'd0, 16'd212, "step 1 add0 = X_1");
        step;
        check(2'd2, 6'd0, 16'd212, "after step 1 r0 = X_1");
        check_state(8'd2, 12'b000000000011);
        check(2'd0, 6'd0, 16'd416, "step 2 add0 = Y_1");
        check(2'd0, 6'd1, 16'd204, "step 2 sub0 = Z_1");
        step;
        check(2'd2, 6'd1, 16'd416, "after step 2 r1 = Y_1");
        check(2'd2, 6'd2, 16'd204, "after step 2 r2 = Z_1");
        check_state(8'd3, 12'b000000000100);
        check(2'd0, 6'd2, 16'd1632, "step 3 mul0 = Q_1");
        step;
        check(2'd2, 6'd3, 16'd1632, "after step 3 r3 = Q_1");
        check_state(8'd4, 12'd0);
        check(2'd1, 6'd0, 16'd212, "output X");
        check(2'd1, 6'd1, 16'd416, "output Y");
        check(2'd1, 6'd2, 16'd204, "output Z");
        check(2'd1, 6'd3, 16'd1632, "output Q");

        if (errors == 0)
            $display("PASS: 5 vectors, %0d checks", checks);
        else
            $display("FAIL: %0d of %0d checks failed", errors, checks);
        $finish;
    end
endmodule
